package dev.wildcraft.test;
import dev.wildcraft.client.animation.rig.*;
import dev.wildcraft.client.combat.CombatOptions;
import dev.wildcraft.client.input.ActionInput;
import dev.wildcraft.client.render.BackTransitions;
import dev.wildcraft.equipment.*;
import dev.wildcraft.player.PlayerStamina;
import java.util.*;
import net.fabricmc.fabric.api.client.gametest.v1.*;
import net.fabricmc.fabric.api.client.gametest.v1.context.*;
import net.minecraft.client.*;
import net.minecraft.client.gui.screens.PauseScreen;
import net.minecraft.client.gui.screens.inventory.InventoryScreen;
import net.minecraft.client.renderer.entity.state.AvatarRenderState;
import net.minecraft.client.resources.DefaultPlayerSkin;
import net.minecraft.core.BlockPos;
import net.minecraft.world.InteractionHand;
import net.minecraft.world.entity.*;
import net.minecraft.world.entity.player.*;
import net.minecraft.world.item.*;
import net.minecraft.world.level.block.Blocks;

/** Actual used bow reference and native slot changes; no source shot or outgoing proxy. */
public final class BowTransitionRigClientTest implements FabricClientGameTest {
    private static void check(boolean ok,String message){if(!ok)throw new AssertionError(message);}
    private static AvatarRenderState state(Minecraft c){return (AvatarRenderState)c.getEntityRenderDispatcher().getRenderer(c.player).createRenderState(c.player,1);}
    private static boolean active(Minecraft c){var f=state(c).getData(CombatRigLayer.FRAME);return f!=null&&f.clip().startsWith("bow_equipment_");}
    private static float progress(Minecraft c){var s=BackTransitions.forArm(state(c),c.player.getMainArm());return s==null?1:s.progress();}
    private static PlayerSkin skin(PlayerModelType type){for(int i=0;i<100;i++){var s=DefaultPlayerSkin.get(new UUID(0,i));if(s.model()==type)return s;}throw new AssertionError("Native skin");}
    private static void select(ClientGameTestContext c,int slot,Item item){c.getInput().pressKey(v->v.keyHotbarSlots[slot]);c.waitFor(v->v.player.getInventory().getSelectedSlot()==slot&&(item==Items.AIR?v.player.getMainHandItem().isEmpty():v.player.getMainHandItem().is(item)));}
    private static void done(ClientGameTestContext c){c.waitFor(v->v.player.getAttached(BackEquipment.VISUAL)!=null&&v.player.getAttached(BackEquipment.VISUAL).ranged().owner()==(v.player.getMainHandItem().is(Items.BOW)?1:3)&&progress(v)==1);check(c.computeOnClient(v->!active(v)),"Original settle completion relinquishes source bow gesture");}
    private static void prepare(ClientGameTestContext c,TestSingleplayerContext w,PlayerModelType type,HumanoidArm arm,boolean carry){
        c.getInput().releaseKey(v->v.keyUse);c.waitTicks(2);w.getServer().runOnServer(s->{var p=s.getPlayerList().getPlayers().getFirst();p.getInventory().clearContent();p.getInventory().setSelectedSlot(0);p.setMainArm(arm);p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(Items.BOW));p.setItemInHand(InteractionHand.OFF_HAND,carry?new ItemStack(Items.SHIELD):ItemStack.EMPTY);p.getInventory().setItem(8,new ItemStack(Items.TORCH));p.getInventory().setItem(10,new ItemStack(Items.ARROW,32));p.teleportTo(p.level(),.5,120,.5,Set.of(),0,0,true);p.setHealth(20);p.setInvulnerableTime(0);PlayerStamina.fill(p);p.inventoryMenu.broadcastChanges();});select(c,0,Items.BOW);c.waitFor(v->v.player.getMainArm()==arm&&v.player.onGround());c.runOnClient(v->{v.player.setYRot(0);v.player.setXRot(-15);RigAudit.fixture=skin(type);RigAudit.enabled=true;BowTransitionAudit.enabled=false;v.options.setCameraType(CameraType.THIRD_PERSON_BACK);});c.waitFor(v->ActionInput.tickFrame().gameplay());c.waitTicks(8);
        c.getInput().holdKey(v->v.keyUse);c.waitFor(v->v.player.isUsingItem()&&v.player.getTicksUsingItem()>=20);c.getInput().releaseKey(v->v.keyUse);c.waitFor(v->!v.player.isUsingItem()&&v.player.getMainHandItem().getDamageValue()==1&&v.player.getAttached(BackEquipment.VISUAL)!=null&&v.player.getAttached(BackEquipment.VISUAL).ranged().owner()==1);c.waitTicks(8);w.getServer().runOnServer(s->{var p=s.getPlayerList().getPlayers().getFirst();check(p.getInventory().getItem(10).getCount()==31,"Actual original native arrow consumes one ammo/wear, with bow registered by actual use");});c.runOnClient(v->{v.player.setXRot(0);RigAudit.begin();BowTransitionAudit.begin();});
    }
    @Override public void runTest(ClientGameTestContext c){var options=CombatOptions.get();int oldFollow=options.follow;
        try(TestSingleplayerContext w=c.worldBuilder().create()){
            w.getConnection().waitForChunksRender();w.getServer().runCommand("gamemode survival @p");w.getServer().runCommand("time set day");w.getServer().runOnServer(s->{for(int x=-8;x<=8;x++)for(int z=-8;z<=12;z++)s.overworld().setBlockAndUpdate(new BlockPos(x,119,z),Blocks.STONE.defaultBlockState());s.getPlayerList().getPlayers().getFirst().teleportTo(.5,120,.5);});c.waitFor(v->v.player.getY()>119);c.getInput().resizeWindow(1280,960);c.runOnClient(v->{options.follow=0;v.options.guiScale().set(2);});
            for(var type:new PlayerModelType[]{PlayerModelType.WIDE,PlayerModelType.SLIM})for(var arm:HumanoidArm.values())for(boolean carry:new boolean[]{false,true}){
                prepare(c,w,type,arm,carry);String suffix=(carry?"shield":"empty")+"_"+(arm==HumanoidArm.RIGHT?"R":"L");select(c,7,Items.AIR);c.waitFor(v->BowTransitionAudit.full>0&&BowTransitionAudit.clip.equals("bow_equipment_stow_back_"+suffix)&&BowTransitionAudit.backGpu>0);c.takeScreenshot("bow-source-stow-"+type+"-"+suffix);done(c);
                c.runOnClient(v->{RigAudit.begin();BowTransitionAudit.begin();});select(c,0,Items.BOW);c.waitFor(v->BowTransitionAudit.full>0&&BowTransitionAudit.clip.equals("bow_equipment_draw_back_"+suffix)&&RigAudit.hands>0);check(c.computeOnClient(v->RigAudit.texture.equals(RigAudit.fixture.body().texturePath().toString())),"Actual native bow/skin GPU");c.takeScreenshot("bow-source-draw-"+type+"-"+suffix);done(c);w.getServer().runOnServer(s->{var p=s.getPlayerList().getPlayers().getFirst();check(p.getMainHandItem().getDamageValue()==1&&p.getInventory().getItem(10).getCount()==31&&p.getInventory().getItem(0).getCount()==1&&PlayerStamina.get(p).stamina()==100,"Source take/stow has no extra shot/ammo/wear/duplicate inventory/cost");});
            }
            prepare(c,w,PlayerModelType.SLIM,HumanoidArm.LEFT,true);select(c,7,Items.AIR);done(c);c.runOnClient(v->{v.options.framerateLimit().set(10);BowTransitionAudit.begin();});select(c,0,Items.BOW);c.waitFor(v->BowTransitionAudit.full>0);c.takeScreenshot("bow-source-real-10fps");done(c);c.runOnClient(v->v.options.framerateLimit().set(120));
            select(c,7,Items.AIR);done(c);select(c,0,Items.BOW);c.waitFor(v->active(v));c.setScreen(()->new PauseScreen(true));c.waitFor(Minecraft::isPaused);float frozen=c.computeOnClient(BowTransitionRigClientTest::progress);check(frozen<1,"Actual pause retains native live bow settle");long until=System.nanoTime()+300_000_000L;c.waitFor(v->System.nanoTime()>until);check(c.computeOnClient(v->active(v)&&Math.abs(progress(v)-frozen)<.001F),"Actual .32 Settle and source freeze");c.takeScreenshot("bow-source-real-pause");c.setScreen(()->null);done(c);
            select(c,7,Items.AIR);done(c);w.getServer().runCommand("tick rate 5");c.runOnClient(v->BowTransitionAudit.begin());long started=System.nanoTime();select(c,0,Items.BOW);c.waitFor(v->BowTransitionAudit.full>0);c.takeScreenshot("bow-source-real-5tps");done(c);check(System.nanoTime()-started<1_200_000_000L,"Native .32 actual-time clock is not stretched by5TPS");w.getServer().runCommand("tick rate 20");
            select(c,7,Items.AIR);done(c);select(c,0,Items.BOW);c.waitFor(v->active(v));c.setScreen(()->new InventoryScreen(Minecraft.getInstance().player));check(c.computeOnClient(v->!active(v)),"Actual GUI owns bow hands immediately");c.takeScreenshot("bow-source-gui");c.setScreen(()->null);c.waitTicks(3);check(c.computeOnClient(v->!active(v)),"Closed menu cannot replay consumed same-reference transition");
            select(c,7,Items.AIR);done(c);select(c,0,Items.BOW);c.waitFor(v->active(v));select(c,8,Items.TORCH);check(c.computeOnClient(v->!active(v)),"Actual new torch owns hand, no outgoing bow proxy");c.takeScreenshot("bow-source-new-torch");
            select(c,7,Items.AIR);done(c);select(c,0,Items.BOW);c.waitFor(v->active(v));c.getInput().holdKey(v->v.keyUse);c.waitFor(v->v.player.isUsingItem()&&v.player.getUsedItemHand()==InteractionHand.MAIN_HAND);check(c.computeOnClient(v->!active(v)),"Actual use/draw owns bow immediately");c.takeScreenshot("bow-source-real-use-handoff");c.waitFor(v->v.player.getTicksUsingItem()>=20);c.getInput().releaseKey(v->v.keyUse);c.waitFor(v->!v.player.isUsingItem()&&v.player.getMainHandItem().getDamageValue()==2);w.getServer().runOnServer(s->{var p=s.getPlayerList().getPlayers().getFirst();check(p.getInventory().getItem(10).getCount()==30&&p.getMainHandItem().getDamageValue()==2,"Actual new native release yields exactly second ammo/wear, no source shot");});
            select(c,7,Items.AIR);done(c);select(c,0,Items.BOW);c.waitFor(v->active(v));w.getServer().runOnServer(s->{var p=s.getPlayerList().getPlayers().getFirst();p.hurtServer(s.overworld(),p.damageSources().generic(),1);});c.waitFor(v->v.player.getHealth()<20&&v.player.hurtTime>0);check(c.computeOnClient(v->!active(v)),"Real damage owns body without bow-art immunity");c.takeScreenshot("bow-source-real-hurt");c.waitTicks(12);
            select(c,7,Items.AIR);done(c);w.getServer().runOnServer(s->{var p=s.getPlayerList().getPlayers().getFirst();p.getInventory().setItem(1,p.getInventory().getItem(0).copy());p.inventoryMenu.broadcastChanges();});select(c,1,Items.BOW);c.waitTicks(2);check(c.computeOnClient(v->!active(v)&&!BackEquipment.view(v.player).ranged().isEmpty()),"Identical-looking spare cannot draw the recorded bow or hide it");c.takeScreenshot("bow-source-native-spare");
            select(c,7,Items.AIR);done(c);w.getServer().runOnServer(s->{var p=s.getPlayerList().getPlayers().getFirst();p.setItemSlot(EquipmentSlot.CHEST,new ItemStack(Items.ELYTRA));p.inventoryMenu.broadcastChanges();});c.waitFor(v->v.player.getItemBySlot(EquipmentSlot.CHEST).is(Items.ELYTRA));select(c,0,Items.BOW);c.waitTicks(1);check(c.computeOnClient(v->!active(v)&&state(v).getDataOrDefault(BackTransitions.WAIST,false)),"Actual elytra waist uses prior native layout and gesture");c.takeScreenshot("bow-source-native-waist");
            System.out.println("C6V actual used bow/native reference and instant hand/back owner16 source cases, real original bow/skin GPU and no extra native ammo/wear/cost PASS; 10FPS/pause/5TPS/GUI/newitem/use-original second shot/hurt/spare/waist PASS; advanced lifecycle pending");
        }finally{c.getInput().releaseKey(v->v.keyUse);c.runOnClient(v->{BowTransitionAudit.enabled=false;RigAudit.enabled=false;RigAudit.fixture=null;options.follow=oldFollow;v.options.framerateLimit().set(120);v.options.setCameraType(CameraType.FIRST_PERSON);});}
    }
}
